import { exhaustiveCheck } from "@/core/helpers";
import {
  GhostButton,
  OutlineButton,
  PrimaryButton,
  SecondaryButton,
} from "@/core/components/primitives/parks-button/parks-button";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";
import styles from "./banner.module.less";
import { PropsWithChildren } from "react";
import { HTMLMotionProps, motion } from "framer-motion";

export const headingLevels = ["h1", "h2", "h3", "h4", "h5", "h6", "p", "span", "div"] as const;
export type HeadingLevel = (typeof headingLevels)[number];

export const themingTypes = ["information", "warning", "darkWarning", "critical", "success", "inheritTheme"] as const;
export type ThemingType = (typeof themingTypes)[number];

export const arrowPositions = ["top", "right", "bottom", "left"] as const;
export type ArrowPosition = (typeof arrowPositions)[number];

export const announcementTypes = ["off", "polite", "assertive"] as const;
export type AnnouncementType = (typeof announcementTypes)[number];

export type BannerProps = {
  /** PS! If you add a new banner type, don't forget to:
   - add new variables in theming\component.less
   - add new case in getIconFromType  */
  type: ThemingType;
  heading: string;
  paragraph?: string;
  /** The id prop could be useful e.g when improving accessibility through aria-attributes */
  id?: string;
  /** For semantic purposes (accessibility) */
  headingLevel?: HeadingLevel;
  /** Border will be hidden if arrow is shown */
  border?: boolean;
  arrow?: ArrowPosition;
  buttonText?: string;
  buttonVariant?: "PrimaryButton" | "SecondaryButton" | "GhostButton" | "OutlineButton";
  center?: boolean;
  hideIcon?: boolean;
  /** Controls whether the banner should be announced by assistive technologies */
  announcement?: AnnouncementType;
  onButtonClick?: () => void;
  onClose?: () => void;
  "data-testid"?: string;
};

const Banner = ({
  type,
  heading,
  paragraph,
  id,
  headingLevel: HeadingLevel = "span",
  border = false,
  arrow,
  buttonText,
  buttonVariant: ButtonVariant = "OutlineButton",
  center = false,
  hideIcon = false,
  announcement = "off",
  onClose,
  onButtonClick,
  children,
  "data-testid": dataTestId,
  ...rest
}: PropsWithChildren<BannerProps & HTMLMotionProps<"div">>) => {
  return (
    <motion.div
      data-type={type}
      data-has-border={border}
      data-has-arrow={!!arrow}
      data-hide-close-button={!onClose}
      data-hide-icon={hideIcon}
      data-arrow-position={arrow}
      data-is-centered={center}
      className={styles.wrapper}
      id={id}
      role={getAnnouncementRole(announcement)}
      data-testid={dataTestId}
      {...rest}
    >
      {!hideIcon && <Icon name={getIconFromType(type)} size="xl" className={styles.icon} />}
      <HeadingLevel className={`${styles.heading} bold`}>{heading}</HeadingLevel>
      {onClose && <GhostButton iconCenterNew="close" iconSize="xxl" className={styles.closeButton} onClick={onClose} />}
      {paragraph && <p className={styles.paragraph}>{paragraph}</p>}
      {children && <div className={styles.children}>{children}</div>}
      {onButtonClick && buttonText && (
        <BannerButton
          buttonText={buttonText}
          buttonVariant={ButtonVariant}
          onButtonClick={onButtonClick}
          dataTestId={`${dataTestId}-button`}
        />
      )}
    </motion.div>
  );
};

const getAnnouncementRole = (announcement: AnnouncementType) => {
  switch (announcement) {
    case "off":
      return undefined;
    case "polite":
      return "status" as const;
    case "assertive":
      return "alert" as const;
    default:
      return exhaustiveCheck(announcement);
  }
};

const getIconFromType = (type: BannerProps["type"]): IconName => {
  switch (type) {
    case "information":
      return "info";
    case "warning":
      return "warning";
    case "darkWarning":
      return "warning";
    case "critical":
      return "error";
    case "success":
      return "check";
    case "inheritTheme":
      return "info";
    default:
      return exhaustiveCheck(type);
  }
};

const BannerButton = ({
  buttonText,
  buttonVariant,
  onButtonClick,
  dataTestId,
}: {
  buttonText: NonNullable<BannerProps["buttonText"]>;
  buttonVariant: NonNullable<BannerProps["buttonVariant"]>;
  onButtonClick: NonNullable<BannerProps["onButtonClick"]>;
  dataTestId?: string;
}) => {
  switch (buttonVariant) {
    case "PrimaryButton":
      return <PrimaryButton className={styles.button} label={buttonText} onClick={onButtonClick} testId={dataTestId} />;
    case "SecondaryButton":
      return (
        <SecondaryButton className={styles.button} label={buttonText} onClick={onButtonClick} testId={dataTestId} />
      );
    case "GhostButton":
      return <GhostButton className={styles.button} label={buttonText} onClick={onButtonClick} testId={dataTestId} />;
    case "OutlineButton":
      return <OutlineButton className={styles.button} label={buttonText} onClick={onButtonClick} testId={dataTestId} />;
    default:
      return exhaustiveCheck(buttonVariant);
  }
};

export default Banner;
